import Foundation
import Testing
@testable import AvastShellApp

struct HistoryStoreTests {
    @Test
    func emptyStoreSeedsOneRecentWeeklyRecord() throws {
        let now = Date(timeIntervalSince1970: 1_781_621_000)
        let store = HistoryStore(fileURL: uniqueFileURL(), now: { now })

        let snapshot = try store.load()

        #expect(snapshot.records.count == 1)
        #expect(snapshot.records[0].kind == .weeklyAutomatic)
        #expect(snapshot.lastAutoGeneratedAt == now)
    }

    @Test
    func saveThenReloadPreservesRecords() throws {
        let now = Date(timeIntervalSince1970: 1_781_621_000)
        let fileURL = uniqueFileURL()
        let store = HistoryStore(fileURL: fileURL, now: { now })
        var snapshot = try store.load()
        let extraRecord = ScanFactory.makeCompletedRecord(kind: .deep, now: now, fileCount: 44_000_000)
        snapshot.records.insert(extraRecord, at: 0)

        try store.save(snapshot)

        let reloaded = try HistoryStore(fileURL: fileURL, now: { now }).load()
        #expect(reloaded.records.first == extraRecord)
        #expect(reloaded.records.count == 2)
    }

    @Test
    func loadingAfterSevenDaysAppendsOneAdditionalWeeklyRecord() throws {
        let start = Date(timeIntervalSince1970: 1_781_621_000)
        let later = start.addingTimeInterval(8 * 24 * 60 * 60)
        let fileURL = uniqueFileURL()

        _ = try HistoryStore(fileURL: fileURL, now: { start }).load()
        let updated = try HistoryStore(fileURL: fileURL, now: { later }).load()

        #expect(updated.records.count == 2)
        #expect(updated.records[0].kind == .weeklyAutomatic)
        #expect(updated.lastAutoGeneratedAt == later)
    }

    @Test
    func deleteRemovesRequestedRecord() throws {
        let now = Date(timeIntervalSince1970: 1_781_621_000)
        let fileURL = uniqueFileURL()
        let store = HistoryStore(fileURL: fileURL, now: { now })
        var snapshot = try store.load()
        let extraRecord = ScanFactory.makeCompletedRecord(kind: .smart, now: now, fileCount: 55_000_000)
        snapshot.records.insert(extraRecord, at: 0)
        try store.save(snapshot)

        let updated = try store.deleteRecord(id: extraRecord.id)

        #expect(updated.records.count == 1)
        #expect(updated.records.contains(where: { $0.id == extraRecord.id }) == false)
    }

    @Test
    func keepsRecentDatesAndRemovesRecordsOlderThanOneMonth() throws {
        let now = Date(timeIntervalSince1970: 1_794_308_400)
        let cutoff = Calendar.current.date(byAdding: .month, value: -1, to: now)!
        let store = HistoryStore(fileURL: uniqueFileURL(), now: { now })
        let yesterday = ScanFactory.makeCompletedRecord(kind: .deep, now: now.addingTimeInterval(-86_400))
        let twoDaysAgo = ScanFactory.makeCanceledRecord(kind: .deep, now: now.addingTimeInterval(-172_800))
        let boundary = ScanFactory.makeCompletedRecord(kind: .deep, now: cutoff)
        let expired = ScanFactory.makeCompletedRecord(kind: .deep, now: cutoff.addingTimeInterval(-1))
        try store.save(ScanHistorySnapshot(records: [expired, twoDaysAgo, boundary, yesterday], lastAutoGeneratedAt: now))
        let restored = try store.load()
        #expect(restored.records == [yesterday, twoDaysAgo, boundary])
    }

    @Test
    func reopeningAfterOneMonthPrunesExpiredHistory() throws {
        let start = Date(timeIntervalSince1970: 1_781_621_000)
        let fileURL = uniqueFileURL()
        let oldStore = HistoryStore(fileURL: fileURL, now: { start })
        let original = try oldStore.load().records[0]
        let later = start.addingTimeInterval(40 * 86_400)
        let reopened = try HistoryStore(fileURL: fileURL, now: { later }).load()
        #expect(!reopened.records.contains(where: { $0.id == original.id }))
        #expect(reopened.records.count == 1)
    }

    @Test
    func settingsAndScansShareOneJSONLFile() throws {
        let now = Date(timeIntervalSince1970: 1_781_621_000)
        let store = HistoryStore(fileURL: uniqueFileURL(), now: { now })
        let settings = AppSettings(historyRetentionMonths: 1, lastLaunchedAt: now, lastUpdatedAt: now.addingTimeInterval(-1800))
        let record = ScanFactory.makeCompletedRecord(kind: .deep, now: now)
        let snapshot = ScanHistorySnapshot(records: [record], lastAutoGeneratedAt: now, settings: settings)
        try store.save(snapshot)
        let lines = try String(contentsOf: store.fileURL, encoding: .utf8).split(separator: "\n")
        #expect(lines.count == 2)
        let objects = try lines.map { try JSONSerialization.jsonObject(with: Data($0.utf8)) as! [String: Any] }
        #expect(objects[0]["type"] as? String == "settings")
        #expect(objects[1]["type"] as? String == "scan")
        #expect(try store.load() == snapshot)
    }

    @Test
    func importsLegacyJSONWithoutDuplicatingOrReimportingDeletedRecords() throws {
        let now = Date(timeIntervalSince1970: 1_781_621_000)
        let source = uniqueFileURL()
        let destination = HistoryStore(fileURL: uniqueFileURL(), now: { now })
        let record = ScanFactory.makeCompletedRecord(kind: .deep, now: now.addingTimeInterval(-86_400))
        let encoder = JSONEncoder()
        encoder.dateEncodingStrategy = .iso8601
        let oldData = try encoder.encode(ScanHistorySnapshot(records: [record], lastAutoGeneratedAt: now))
        try oldData.write(to: source)
        try destination.migrateLegacyHistory(from: [source, source])
        #expect(try destination.load().records == [record])
        _ = try destination.deleteRecord(id: record.id)
        try destination.migrateLegacyHistory(from: [source])
        #expect(try destination.load().records.isEmpty)
        #expect(try Data(contentsOf: source) == oldData)
    }

    private func uniqueFileURL() -> URL {
        URL(fileURLWithPath: NSTemporaryDirectory())
            .appendingPathComponent(UUID().uuidString)
            .appendingPathExtension("json")
    }
}
